create or replace function app_user_id() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
-- MerkatoLink / fictional demo schema. Apply in Supabase SQL editor in a fresh project.
create extension if not exists pgcrypto;
create sequence if not exists invoice_sequence;
create type app_role as enum('admin','trader_owner','trader_staff','broker','buyer');
create table terras(id bigint generated always as identity primary key,name text unique not null,name_am text,description text not null default '',icon text not null default '✳',created_at timestamptz not null default now());
create table traders(id uuid primary key default gen_random_uuid(),terra_id bigint not null references terras,name text not null,owner_name text not null default '',shop_no text not null,landmark text not null,phone text,telegram text,tin text,license_no text,vat_registered boolean not null default false,verified boolean not null default false,logo_url text,primary_color text not null default '#526747',tagline text not null default '',created_at timestamptz not null default now());
create table profiles(id uuid primary key,role app_role not null default 'buyer',display_name text not null default '');
create table trader_members(user_id uuid references profiles(id) on delete cascade,trader_id uuid references traders on delete cascade,role text check(role in('owner','staff')) not null default 'staff',primary key(user_id,trader_id));
create table brokers(id uuid primary key default gen_random_uuid(),profile_id uuid references profiles,name text not null,phone text,default_commission_pct numeric(5,2) not null default 2 check(default_commission_pct between 0 and 100));
create table buyers(id uuid primary key default gen_random_uuid(),profile_id uuid references profiles,name text not null,business_name text not null default '',phone text,area text not null default '',credit_limit numeric(14,2) not null default 0 check(credit_limit>=0));
create table products(id uuid primary key default gen_random_uuid(),trader_id uuid not null references traders on delete cascade,name text not null,name_am text,category text not null default 'General',base_unit text not null default 'piece',is_imported boolean not null default false,target_margin numeric(5,2) not null default 20 check(target_margin between 0 and 99.99),is_active boolean not null default true,created_at timestamptz not null default now());
create table product_units(id uuid primary key default gen_random_uuid(),product_id uuid not null references products on delete cascade,unit_name text not null,base_qty numeric(14,3) not null default 1 check(base_qty>0),min_order_qty numeric(14,3) not null default 1 check(min_order_qty>0),retail_price numeric(14,2) not null check(retail_price>=0),unique(product_id,unit_name));
create table price_tiers(id bigint generated always as identity primary key,product_unit_id uuid not null references product_units on delete cascade,min_qty numeric(14,3) not null check(min_qty>0),price numeric(14,2) not null check(price>=0),unique(product_unit_id,min_qty));
create table locations(id uuid primary key default gen_random_uuid(),trader_id uuid not null references traders on delete cascade,name text not null,type text not null check(type in('shop','warehouse','truck')));
create table stock(location_id uuid references locations on delete cascade,product_id uuid references products on delete cascade,qty numeric(14,3) not null default 0 check(qty>=0),primary key(location_id,product_id));
create table exchange_rates(id bigint generated always as identity primary key,rate_date timestamptz not null default now(),usd_etb numeric(12,4) not null check(usd_etb>0),source text not null default 'demo',created_by uuid references profiles,created_at timestamptz not null default now());
create table tax_settings(id bigint generated always as identity primary key,name text not null,rate numeric(8,5) not null check(rate>=0),base text not null check(base in('cif','cif_duty','running_total','custom')),sort_order int not null,effective_from date not null default current_date,effective_to date,unique(name,effective_from));
create table product_costs(id bigint generated always as identity primary key,product_id uuid not null references products on delete cascade,fob_usd numeric(14,4) not null check(fob_usd>=0),freight_usd numeric(14,4) not null default 0,insurance_usd numeric(14,4) not null default 0,duty_rate numeric(8,5) not null default 0,excise_rate numeric(8,5) not null default 0,effective_from date not null default current_date);
create table orders(id uuid primary key default gen_random_uuid(),trader_id uuid not null references traders,buyer_id uuid not null references buyers,broker_id uuid references brokers,status text not null default 'new' check(status in('new','confirmed','fulfilled','cancelled')),payment_terms text not null check(payment_terms in('cash','transfer','mobile_money','credit')),transfer_reference text,due_date date,delivery_type text not null default 'pickup' check(delivery_type in('pickup','porter','truck')),delivery_fee numeric(14,2) not null default 0 check(delivery_fee>=0),subtotal numeric(14,2) not null default 0 check(subtotal>=0),vat numeric(14,2) not null default 0 check(vat>=0),total numeric(14,2) not null default 0 check(total>=0),invoice_no text unique,check(payment_terms<>'credit' or due_date is not null),created_at timestamptz not null default now());
create table order_items(id bigint generated always as identity primary key,order_id uuid not null references orders on delete cascade,product_unit_id uuid not null references product_units,quantity numeric(14,3) not null check(quantity>0),unit_price numeric(14,2) not null check(unit_price>=0));
create table payments(id bigint generated always as identity primary key,order_id uuid not null references orders on delete cascade,method text not null check(method in('cash','telebirr','bank','other')),amount numeric(14,2) not null check(amount>0),reference text,paid_at timestamptz not null default now());
create table broker_commissions(id bigint generated always as identity primary key,order_id uuid unique not null references orders on delete cascade,broker_id uuid not null references brokers,pct numeric(5,2) not null,amount numeric(14,2) not null,status text not null default 'pending' check(status in('pending','paid','void')));
create table offers(id bigint generated always as identity primary key,order_id uuid not null references orders on delete cascade,from_role text not null check(from_role in('buyer','trader')),price numeric(14,2) not null,note text not null default '',created_at timestamptz not null default now());
create table price_board(id bigint generated always as identity primary key,terra_id bigint not null references terras,item_name text not null,unit text not null,price numeric(14,2) not null check(price>=0),reported_by uuid references profiles,price_date date not null default current_date);
create table price_history(id bigint generated always as identity primary key,product_id uuid not null references products,old_price numeric(14,2) not null,new_price numeric(14,2) not null,rate_id bigint references exchange_rates,changed_at timestamptz not null default now());
create table audit_log(id bigint generated always as identity primary key,user_id uuid,action text not null,table_name text not null,record_id text,details jsonb not null default '{}',changed_at timestamptz not null default now());
create index on orders(trader_id,created_at desc);create index on payments(order_id);create index on order_items(product_unit_id);create index on exchange_rates(rate_date desc);create index on products(trader_id,is_active);create index on price_board(terra_id,price_date desc);
create or replace function calc_landed_cost(p_product uuid,p_rate bigint) returns table(cif_usd numeric,duty_usd numeric,excise_usd numeric,vat_usd numeric,surtax_usd numeric,withholding_usd numeric,clearing_usd numeric,landed_etb numeric,rate numeric) language sql stable as $$ with c as(select pc.*,coalesce((select r.usd_etb from exchange_rates r where r.id=p_rate),(select r.usd_etb from exchange_rates r order by rate_date desc limit 1),1) fx from product_costs pc where pc.product_id=p_product order by effective_from desc limit 1),base as(select *,fob_usd+freight_usd+insurance_usd cif from c),calc as(select *,cif*duty_rate duty,(cif+cif*duty_rate)*excise_rate excise from base),tax as(select *, (cif+duty+excise)*coalesce((select rate from tax_settings where name='VAT' and effective_from<=current_date and (effective_to is null or effective_to>=current_date) order by effective_from desc limit 1),.15) vat from calc) select cif,duty,excise,vat,(cif+duty+excise+vat)*coalesce((select rate from tax_settings where name='Surtax' and effective_from<=current_date and (effective_to is null or effective_to>=current_date) order by effective_from desc limit 1),0),cif*coalesce((select rate from tax_settings where name='Withholding' and effective_from<=current_date and (effective_to is null or effective_to>=current_date) order by effective_from desc limit 1),0),coalesce((select rate from tax_settings where name='Clearing USD' and effective_from<=current_date and (effective_to is null or effective_to>=current_date) order by effective_from desc limit 1),0),((cif+duty+excise+vat+(cif+duty+excise+vat)*coalesce((select rate from tax_settings where name='Surtax' and effective_from<=current_date and (effective_to is null or effective_to>=current_date) order by effective_from desc limit 1),0)+cif*coalesce((select rate from tax_settings where name='Withholding' and effective_from<=current_date and (effective_to is null or effective_to>=current_date) order by effective_from desc limit 1),0)+coalesce((select rate from tax_settings where name='Clearing USD' and effective_from<=current_date and (effective_to is null or effective_to>=current_date) order by effective_from desc limit 1),0))*fx)/greatest((select coalesce(sum(base_qty),1) from product_units where product_id=p_product),1),fx from tax $$;
create or replace view v_product_margin with (security_invoker=true) as select p.id product_id,p.trader_id,p.name,pu.id product_unit_id,pu.unit_name,pu.retail_price,coalesce((select landed_etb from calc_landed_cost(p.id,null)),0) landed_cost_etb,case when pu.retail_price=0 then 0 else round((pu.retail_price-coalesce((select landed_etb from calc_landed_cost(p.id,null)),0))/pu.retail_price*100,1) end margin_pct,p.target_margin from products p join product_units pu on pu.product_id=p.id where p.is_active;
create or replace view v_rate_shock with (security_invoker=true) as select m.*,m.margin_pct<m.target_margin below_target from v_product_margin m;
create or replace view v_receivables_aging with (security_invoker=true) as with paid as(select order_id,sum(amount) amount from payments group by order_id),bal as(select o.*,b.name buyer_name,greatest(o.total-coalesce(p.amount,0),0) balance,coalesce(o.due_date,current_date) due from orders o join buyers b on b.id=o.buyer_id left join paid p on p.order_id=o.id where o.payment_terms='credit' and o.status<>'cancelled') select trader_id,buyer_id,buyer_name,sum(balance) outstanding,sum(case when current_date<=due then balance else 0 end) current_due,sum(case when current_date-due between 1 and 7 then balance else 0 end) late_1_7,sum(case when current_date-due between 8 and 30 then balance else 0 end) late_8_30,sum(case when current_date-due>30 then balance else 0 end) late_over_30 from bal group by trader_id,buyer_id,buyer_name;
create or replace view v_broker_earnings with (security_invoker=true) as select bc.broker_id,sum(bc.amount) filter(where bc.status='pending') pending,sum(bc.amount) filter(where bc.status='paid') paid,count(*) deals from broker_commissions bc group by bc.broker_id;
create or replace view v_daily_revenue with (security_invoker=true) as select trader_id,date_trunc('day',created_at)::date day,count(*) orders,sum(total) revenue from orders where status in('confirmed','fulfilled') group by trader_id,2;
create or replace view v_low_stock with (security_invoker=true) as select p.trader_id,p.id product_id,p.name,l.name location,s.qty from stock s join products p on p.id=s.product_id join locations l on l.id=s.location_id where s.qty<10;
create or replace view v_trader_reputation with (security_invoker=true) as select trader_id,round(100.0*count(*) filter(where status='fulfilled')/greatest(count(*) filter(where status<>'cancelled'),1),0)::int reputation_score,count(*) orders from orders group by trader_id;
create or replace function audit_row() returns trigger language plpgsql security definer as $$ begin insert into audit_log(user_id,action,table_name,record_id,details) values(app_user_id(),tg_op,tg_table_name,coalesce(new.id::text,old.id::text),jsonb_build_object('after',to_jsonb(new),'before',to_jsonb(old))); return coalesce(new,old); end $$;
create or replace function order_side_effects() returns trigger language plpgsql security definer as $$ declare x record; pct numeric; begin if new.status='confirmed' and old.status is distinct from 'confirmed' then for x in select pu.product_id,oi.quantity*pu.base_qty qty from order_items oi join product_units pu on pu.id=oi.product_unit_id where oi.order_id=new.id loop update stock set qty=qty-x.qty where product_id=x.product_id and location_id in(select id from locations where trader_id=new.trader_id) and qty>=x.qty; if not found then raise exception 'Insufficient stock for product %',x.product_id; end if; end loop; if new.broker_id is not null then select default_commission_pct into pct from brokers where id=new.broker_id; insert into broker_commissions(order_id,broker_id,pct,amount) values(new.id,new.broker_id,coalesce(pct,0),new.subtotal*coalesce(pct,0)/100) on conflict(order_id) do nothing; end if; end if; return new; end $$;
create trigger orders_confirm_side_effects after update of status on orders for each row execute function order_side_effects();
create or replace function guard_payment_total() returns trigger language plpgsql as $$ declare oid uuid; total_due numeric; already numeric; begin oid=coalesce(new.order_id,old.order_id); select total into total_due from orders where id=oid; select coalesce(sum(amount),0) into already from payments where order_id=oid and id<>coalesce(new.id,-1); if already+coalesce(new.amount,0)>total_due then raise exception 'Payment exceeds order balance'; end if; return new; end $$;
create trigger payment_limit before insert or update on payments for each row execute function guard_payment_total();
create or replace function log_change() returns trigger language plpgsql as $$ begin perform audit_row(); return coalesce(new,old); end $$;
create trigger audit_rate after insert or update or delete on exchange_rates for each row execute function log_change();create trigger audit_tax after insert or update or delete on tax_settings for each row execute function log_change();create trigger audit_payment after insert or update or delete on payments for each row execute function log_change();create trigger audit_price after insert or update or delete on price_tiers for each row execute function log_change();
-- RLS starts deny-by-default. Membership policies scope trader records; platform-admin policies are explicit.
do $$ declare t text; begin foreach t in array array['profiles','terras','traders','trader_members','brokers','buyers','products','product_units','price_tiers','locations','stock','product_costs','tax_settings','exchange_rates','orders','order_items','payments','broker_commissions','offers','price_board','price_history','audit_log'] loop execute format('alter table %I enable row level security',t); end loop; end $$;
create or replace function is_trader_member(target uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from trader_members where trader_id=target and user_id=app_user_id()) $$;
create or replace function is_platform_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=app_user_id() and role='admin') $$;
create or replace function is_trader_member(target uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from trader_members where trader_id=target and user_id=app_user_id()) $$;
create or replace function is_platform_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=app_user_id() and role='admin') $$;
create policy "Public reads terras" on terras for select using(true);
create policy "Profiles self read" on profiles for select using(id=app_user_id() or is_platform_admin());
create policy "Membership self read" on trader_members for select using(user_id=app_user_id() or is_platform_admin());
create policy "Broker self read" on brokers for select using(profile_id=app_user_id() or is_platform_admin());
create policy "Buyer self or trader reads" on buyers for select using(profile_id=app_user_id() or is_platform_admin() or exists(select 1 from orders o where o.buyer_id=buyers.id and is_trader_member(o.trader_id)));
create policy "Trader members manage locations" on locations for all using(is_trader_member(trader_id) or is_platform_admin()) with check(is_trader_member(trader_id) or is_platform_admin());
create policy "Trader members manage stock" on stock for all using(exists(select 1 from locations l where l.id=location_id and (is_trader_member(l.trader_id) or is_platform_admin()))) with check(exists(select 1 from locations l where l.id=location_id and (is_trader_member(l.trader_id) or is_platform_admin())));
create policy "Trader members manage costs" on product_costs for all using(exists(select 1 from products p where p.id=product_id and (is_trader_member(p.trader_id) or is_platform_admin()))) with check(exists(select 1 from products p where p.id=product_id and (is_trader_member(p.trader_id) or is_platform_admin())));
create policy "Trader members manage tiers" on price_tiers for all using(exists(select 1 from product_units u join products p on p.id=u.product_id where u.id=product_unit_id and (is_trader_member(p.trader_id) or is_platform_admin()))) with check(exists(select 1 from product_units u join products p on p.id=u.product_id where u.id=product_unit_id and (is_trader_member(p.trader_id) or is_platform_admin())));
create policy "Trader members manage product units" on product_units for all using(exists(select 1 from products p where p.id=product_id and (is_trader_member(p.trader_id) or is_platform_admin()))) with check(exists(select 1 from products p where p.id=product_id and (is_trader_member(p.trader_id) or is_platform_admin())));
create policy "Public reads price board" on price_board for select using(true);
create policy "Trader manages price history" on price_history for all using(exists(select 1 from products p where p.id=product_id and is_trader_member(p.trader_id))) with check(exists(select 1 from products p where p.id=product_id and is_trader_member(p.trader_id)));
create policy "Platform admins manage tax settings" on tax_settings for all using(is_platform_admin()) with check(is_platform_admin());
create policy "Platform admins manage exchange rates" on exchange_rates for all using(is_platform_admin()) with check(is_platform_admin());
create policy "Audit append only" on audit_log for insert with check(user_id=app_user_id() or is_platform_admin());
create policy "Audit own read" on audit_log for select using(user_id=app_user_id() or is_platform_admin());
create policy "Offer parties read" on offers for select using(exists(select 1 from orders o where o.id=order_id and (is_trader_member(o.trader_id) or o.buyer_id in(select id from buyers where profile_id=app_user_id()))));
create policy "Public verified traders" on traders for select using(verified=true);
create policy "Public active products" on products for select using(is_active=true and exists(select 1 from traders t where t.id=trader_id and t.verified));
create policy "Public unit prices" on product_units for select using(exists(select 1 from products p join traders t on t.id=p.trader_id where p.id=product_id and p.is_active and t.verified));
create policy "Members see own trader" on traders for all using(exists(select 1 from trader_members m where m.trader_id=id and m.user_id=app_user_id()) or exists(select 1 from profiles where id=app_user_id() and role='admin')) with check(exists(select 1 from trader_members m where m.trader_id=id and m.user_id=app_user_id()) or exists(select 1 from profiles where id=app_user_id() and role='admin'));
create policy "Members manage products" on products for all using(exists(select 1 from trader_members m where m.trader_id=products.trader_id and m.user_id=app_user_id()) or exists(select 1 from profiles where id=app_user_id() and role='admin')) with check(exists(select 1 from trader_members m where m.trader_id=products.trader_id and m.user_id=app_user_id()) or exists(select 1 from profiles where id=app_user_id() and role='admin'));
create policy "Members manage orders" on orders for all using(exists(select 1 from trader_members m where m.trader_id=orders.trader_id and m.user_id=app_user_id()) or buyer_id in(select id from buyers where profile_id=app_user_id()) or exists(select 1 from profiles where id=app_user_id() and role='admin')) with check(exists(select 1 from trader_members m where m.trader_id=orders.trader_id and m.user_id=app_user_id()) or buyer_id in(select id from buyers where profile_id=app_user_id()));
create policy "Broker own commissions" on broker_commissions for select using(broker_id in(select id from brokers where profile_id=app_user_id()) or exists(select 1 from trader_members m join orders o on o.trader_id=m.trader_id where o.id=order_id and m.user_id=app_user_id()));
create table if not exists stock_transfers(id bigint generated always as identity primary key,product_id uuid not null references products,from_location uuid not null references locations,to_location uuid not null references locations,quantity numeric(14,3) not null check(quantity>0),status text not null default 'pending' check(status in('pending','completed','cancelled')),created_by uuid references profiles,created_at timestamptz not null default now());
create table if not exists price_board_reports(id bigint generated always as identity primary key,terra_id bigint not null references terras,item_name text not null,unit text not null,price numeric(14,2) not null check(price>=0),reported_by uuid references profiles,reported_at timestamptz not null default now());
create table if not exists price_alerts(id bigint generated always as identity primary key,user_id uuid not null references profiles,terra_id bigint references terras,item_name text not null,target_price numeric(14,2) not null check(target_price>=0),is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists deliveries(id uuid primary key default gen_random_uuid(),order_id uuid unique not null references orders,status text not null default 'pending' check(status in('pending','packed','with_porter','on_truck','delivered')),proof_url text,updated_at timestamptz not null default now());
create table if not exists delivery_events(id bigint generated always as identity primary key,delivery_id uuid not null references deliveries on delete cascade,status text not null,note text not null default '',actor_id uuid references profiles,created_at timestamptz not null default now());
create table if not exists notifications(id bigint generated always as identity primary key,user_id uuid not null references profiles,title text not null,body text not null,channel text not null default 'in_app',read_at timestamptz,created_at timestamptz not null default now());
create table if not exists notification_preferences(user_id uuid primary key references profiles,email_enabled boolean not null default false,sms_enabled boolean not null default false,telegram_enabled boolean not null default false,quiet_start time,quiet_end time);
create table if not exists users(id uuid primary key default gen_random_uuid(),phone text unique,email text unique,password_hash text,created_at timestamptz not null default now(),check(phone is not null or email is not null));

-- Private data helpers and role-specific access defaults for additional workflow tables.
alter table stock_transfers enable row level security;alter table price_board_reports enable row level security;alter table price_alerts enable row level security;alter table deliveries enable row level security;alter table delivery_events enable row level security;alter table notifications enable row level security;alter table notification_preferences enable row level security;alter table users enable row level security;
create policy "Members manage stock transfers" on stock_transfers for all using(exists(select 1 from products p where p.id=product_id and is_trader_member(p.trader_id))) with check(exists(select 1 from products p where p.id=product_id and is_trader_member(p.trader_id)));
create policy "Public reads board reports" on price_board_reports for select using(true);
create policy "Users manage own price alerts" on price_alerts for all using(user_id=app_user_id()) with check(user_id=app_user_id());
create policy "Order parties read deliveries" on deliveries for select using(exists(select 1 from orders o where o.id=order_id and (is_trader_member(o.trader_id) or o.buyer_id in(select id from buyers where profile_id=app_user_id()))));
create policy "Order parties read delivery events" on delivery_events for select using(exists(select 1 from deliveries d join orders o on o.id=d.order_id where d.id=delivery_id and (is_trader_member(o.trader_id) or o.buyer_id in(select id from buyers where profile_id=app_user_id()))));
create policy "Users read own notifications" on notifications for select using(user_id=app_user_id());
create policy "Users manage own notification preferences" on notification_preferences for all using(user_id=app_user_id()) with check(user_id=app_user_id());
create policy "Users read own login record" on users for select using(id=app_user_id());
create policy "Platform admins manage memberships" on trader_members for all using(is_platform_admin()) with check(is_platform_admin());
create policy "Platform admins manage profiles" on profiles for all using(is_platform_admin()) with check(is_platform_admin());
create policy "Platform admins manage brokers" on brokers for all using(is_platform_admin()) with check(is_platform_admin());
create policy "Platform admins manage buyers" on buyers for all using(is_platform_admin()) with check(is_platform_admin());
create or replace function preview_rate_shock(p_new_rate numeric)
returns table(product_id uuid,trader_id uuid,product_name text,unit_name text,old_cost_etb numeric,new_cost_etb numeric,old_margin_pct numeric,new_margin_pct numeric,target_margin numeric,status text,replacement_cost_delta numeric)
language sql stable as $$
with rate_now as(select usd_etb from exchange_rates order by rate_date desc limit 1), cost as(select m.*,r.usd_etb current_rate,case when r.usd_etb>0 then m.landed_cost_etb*p_new_rate/r.usd_etb else m.landed_cost_etb end new_cost from v_product_margin m cross join rate_now r), stock_total as(select product_id,sum(qty) qty from stock group by product_id)
select c.product_id,c.trader_id,c.name,c.unit_name,c.landed_cost_etb,round(c.new_cost,2),c.margin_pct,case when c.retail_price>0 then round((c.retail_price-c.new_cost)/c.retail_price*100,1) else 0 end,c.target_margin,case when c.retail_price<=0 or (c.retail_price-c.new_cost)/c.retail_price*100<c.target_margin then 'Below target' when (c.retail_price-c.new_cost)/c.retail_price*100<c.target_margin+5 then 'Thin' else 'Healthy' end,round(coalesce(st.qty,0)*greatest(c.new_cost-c.landed_cost_etb,0),2)
from cost c left join stock_total st on st.product_id=c.product_id where p_new_rate>0
$$;
create or replace view v_days_of_stock with (security_invoker=true) as
with sold as(select pu.product_id,sum(oi.quantity*pu.base_qty)/30.0 avg_daily from order_items oi join product_units pu on pu.id=oi.product_unit_id join orders o on o.id=oi.order_id where o.status in('confirmed','fulfilled') and o.created_at>=now()-interval '30 days' group by pu.product_id),available as(select product_id,sum(qty) qty from stock group by product_id)
select p.trader_id,p.id product_id,p.name,coalesce(a.qty,0) stock_qty,coalesce(s.avg_daily,0) avg_daily_sales,case when coalesce(s.avg_daily,0)>0 then round(coalesce(a.qty,0)/s.avg_daily,1) else null end days_remaining from products p left join sold s on s.product_id=p.id left join available a on a.product_id=p.id where p.is_active;

create or replace function guard_payment_total() returns trigger language plpgsql as $$ declare oid uuid; total_due numeric; already numeric; begin oid=coalesce(new.order_id,old.order_id); select total into total_due from orders where id=oid for update; select coalesce(sum(amount),0) into already from payments where order_id=oid and id<>coalesce(new.id,-1); if already+coalesce(new.amount,0)>total_due then raise exception 'Payment exceeds order balance'; end if; return new; end $$;
create or replace function order_side_effects() returns trigger language plpgsql security definer set search_path=public as $$
declare item record; commission_pct numeric;
begin
 if new.status='confirmed' and old.status is distinct from 'confirmed' then
  for item in select pu.product_id,sum(oi.quantity*pu.base_qty) quantity from order_items oi join product_units pu on pu.id=oi.product_unit_id where oi.order_id=new.id group by pu.product_id loop
   update stock target set qty=target.qty-item.quantity from (select source.location_id,source.product_id from stock source join locations loc on loc.id=source.location_id where source.product_id=item.product_id and loc.trader_id=new.trader_id and source.qty>=item.quantity order by case when loc.type='shop' then 0 else 1 end limit 1 for update of source skip locked) picked where target.location_id=picked.location_id and target.product_id=picked.product_id;
   if not found then raise exception 'Insufficient stock for product %',item.product_id; end if;
  end loop;
  if new.broker_id is not null then select default_commission_pct into commission_pct from brokers where id=new.broker_id; insert into broker_commissions(order_id,broker_id,pct,amount) values(new.id,new.broker_id,coalesce(commission_pct,0),new.subtotal*coalesce(commission_pct,0)/100) on conflict(order_id) do nothing; end if;
 end if;
 return new;
end $$;
create or replace function enforce_buyer_credit_limit() returns trigger language plpgsql security definer set search_path=public as $$
declare allowed numeric; outstanding numeric;
begin
 if new.payment_terms<>'credit' or new.status='cancelled' then return new; end if;
 select credit_limit into allowed from buyers where id=new.buyer_id for update;
 select coalesce(sum(o.total-coalesce(p.paid,0)),0) into outstanding from orders o left join (select order_id,sum(amount) paid from payments group by order_id) p on p.order_id=o.id where o.buyer_id=new.buyer_id and o.payment_terms='credit' and o.status<>'cancelled' and o.id<>new.id;
 if outstanding+new.total>coalesce(allowed,0) then raise exception 'Buyer credit limit exceeded'; end if;
 return new;
end $$;
create trigger orders_credit_limit_insert before insert on orders for each row execute function enforce_buyer_credit_limit();
create trigger orders_credit_limit_update before update of buyer_id,payment_terms,due_date,total,status on orders for each row execute function enforce_buyer_credit_limit();

ALTER TABLE deliveries ADD COLUMN IF NOT EXISTS delivery_address text;
